const sourceMode = 'yahoo'; // troque para 'stooq' se quiser testar o fallback
if (sourceMode === 'stooq') {
  return [
    { json: { symbol: 'ES.F', label: 'ES', sourceMode, url: 'https://stooq.com/q/l/?s=es.f&f=sd2t2ohlcv&h&e=csv' } },
    { json: { symbol: 'NQ.F', label: 'NQ', sourceMode, url: 'https://stooq.com/q/l/?s=nq.f&f=sd2t2ohlcv&h&e=csv' } },
    { json: { symbol: 'GC.F', label: 'Gold', sourceMode, url: 'https://stooq.com/q/l/?s=gc.f&f=sd2t2ohlcv&h&e=csv' } },
    { json: { symbol: 'DX.F', label: 'DXY', sourceMode, url: 'https://stooq.com/q/l/?s=dx.f&f=sd2t2ohlcv&h&e=csv' } }
  ];
}
return [
  { json: { symbol: 'ES=F', label: 'ES', sourceMode: 'yahoo', url: 'https://query1.finance.yahoo.com/v8/finance/chart/ES=F?interval=1d&range=5d' } },
  { json: { symbol: 'NQ=F', label: 'NQ', sourceMode: 'yahoo', url: 'https://query1.finance.yahoo.com/v8/finance/chart/NQ=F?interval=1d&range=5d' } },
  { json: { symbol: 'GC=F', label: 'Gold', sourceMode: 'yahoo', url: 'https://query1.finance.yahoo.com/v8/finance/chart/GC=F?interval=1d&range=5d' } },
  { json: { symbol: 'DX-Y.NYB', label: 'DXY', sourceMode: 'yahoo', url: 'https://query1.finance.yahoo.com/v8/finance/chart/DX-Y.NYB?interval=1d&range=5d' } }
];

const sourceMode = String($items('Market Symbols', 0, 0)[0]?.json?.sourceMode || 'yahoo').toLowerCase();
const parseYahoo = text => {
  const json = JSON.parse(text);
  const result = json?.chart?.result?.[0];
  const meta = result?.meta;
  if (!meta) return null;
  const closeNum = Number(meta.regularMarketPrice);
  const prevClose = Number(meta.chartPreviousClose);
  if (!Number.isFinite(closeNum) || !Number.isFinite(prevClose) || prevClose === 0) return null;
  return {
    label: meta.symbol,
    close: closeNum,
    previousClose: prevClose,
    high: Number(meta.regularMarketDayHigh),
    low: Number(meta.regularMarketDayLow),
    volume: Number(meta.regularMarketVolume || 0),
    marketTs: Number(meta.regularMarketTime || 0) * 1000,
    pctFromPrevClose: Math.round((((closeNum - prevClose) / prevClose) * 100) * 100) / 100
  };
};
const parseStooq = text => {
  const lines = String(text || '').trim().split(/\r?\n/);
  if (lines.length < 2) return null;
  const row = lines[1].split(',');
  if (row.length < 7 || row[1] === 'N/D') return null;
  const [symbol, date, time, open, high, low, close] = row;
  const openNum = Number(open);
  const closeNum = Number(close);
  if (!Number.isFinite(openNum) || !Number.isFinite(closeNum) || openNum === 0) return null;
  return {
    label: symbol,
    close: closeNum,
    previousClose: openNum,
    high: Number(high),
    low: Number(low),
    volume: 0,
    marketTs: Date.now(),
    pctFromPrevClose: Math.round((((closeNum - openNum) / openNum) * 100) * 100) / 100
  };
};
const labels = {
  'ES=F': 'ES',
  'ES.F': 'ES',
  'NQ=F': 'NQ',
  'NQ.F': 'NQ',
  'GC=F': 'Gold',
  'GC.F': 'Gold',
  'DX-Y.NYB': 'DXY',
  'DX.F': 'DXY'
};
const quotes = [];
for (const item of items) {
  const rawText = typeof item.json === 'string' ? item.json : JSON.stringify(item.json);
  let parsed = null;
  if (sourceMode === 'stooq') {
    parsed = parseStooq(rawText);
  } else {
    parsed = parseYahoo(rawText);
  }
  if (!parsed) continue;
  const label = labels[parsed.label] || labels[item.json.symbol] || item.json.label || parsed.label;
  quotes.push({ ...parsed, label, symbol: item.json.symbol || parsed.label });
}
if (!quotes.length) return [];
const freshestTs = Math.max(...quotes.map(q => q.marketTs || 0));
if (!freshestTs || Date.now() - freshestTs > 12 * 60 * 60 * 1000) return [];
const by = Object.fromEntries(quotes.map(q => [q.label, q]));
const es = by.ES;
const nq = by.NQ;
const dxy = by.DXY;
const gold = by.Gold;
let riskOffScore = 0;
const riskOffReasons = [];
if (es?.pctFromPrevClose <= -0.4) { riskOffScore += 25; riskOffReasons.push(`ES weak ${es.pctFromPrevClose}%`); }
if (es?.pctFromPrevClose <= -0.8) riskOffScore += 20;
if (es?.pctFromPrevClose <= -1.5) riskOffScore += 15;
if (nq?.pctFromPrevClose <= -0.6) { riskOffScore += 25; riskOffReasons.push(`NQ weak ${nq.pctFromPrevClose}%`); }
if (nq?.pctFromPrevClose <= -1.2) riskOffScore += 20;
if (nq?.pctFromPrevClose <= -2.5) riskOffScore += 15;
if (dxy?.pctFromPrevClose >= 0.15) { riskOffScore += 15; riskOffReasons.push(`DXY firm ${dxy.pctFromPrevClose}%`); }
if (dxy?.pctFromPrevClose >= 0.35) riskOffScore += 10;
if (gold?.pctFromPrevClose >= 0.3) { riskOffScore += 15; riskOffReasons.push(`Gold bid ${gold.pctFromPrevClose}%`); }
if (gold?.pctFromPrevClose >= 0.7) riskOffScore += 10;
const equitiesRiskOff = (es?.pctFromPrevClose <= -0.4 ? 1 : 0) + (nq?.pctFromPrevClose <= -0.6 ? 1 : 0);
const safeHavenConfirm = (dxy?.pctFromPrevClose >= 0.15 ? 1 : 0) + (gold?.pctFromPrevClose >= 0.3 ? 1 : 0);
if (equitiesRiskOff >= 1 && safeHavenConfirm >= 1) { riskOffScore += 20; riskOffReasons.push('Risk-off confluence'); }
if (equitiesRiskOff === 2) { riskOffScore += 15; riskOffReasons.push('ES and NQ both weak'); }
let riskOnScore = 0;
const riskOnReasons = [];
if (es?.pctFromPrevClose >= 0.45) { riskOnScore += 25; riskOnReasons.push(`ES strong ${es.pctFromPrevClose}%`); }
if (es?.pctFromPrevClose >= 1.0) riskOnScore += 15;
if (nq?.pctFromPrevClose >= 0.65) { riskOnScore += 25; riskOnReasons.push(`NQ strong ${nq.pctFromPrevClose}%`); }
if (nq?.pctFromPrevClose >= 1.5) riskOnScore += 15;
if (dxy?.pctFromPrevClose <= -0.15) { riskOnScore += 15; riskOnReasons.push(`DXY softer ${dxy.pctFromPrevClose}%`); }
if (dxy?.pctFromPrevClose <= -0.35) riskOnScore += 10;
if (gold?.pctFromPrevClose <= -0.3) { riskOnScore += 10; riskOnReasons.push(`Gold softer ${gold.pctFromPrevClose}%`); }
if ((es?.pctFromPrevClose >= 0.45 || nq?.pctFromPrevClose >= 0.65) && dxy?.pctFromPrevClose <= -0.15) { riskOnScore += 20; riskOnReasons.push('Risk-on confluence'); }
let direction = 'neutral';
let score = 0;
let reasons = [];
if (riskOffScore >= riskOnScore && riskOffScore >= 85) {
  direction = 'risk_off';
  score = riskOffScore;
  reasons = riskOffReasons;
} else if (riskOnScore > riskOffScore && riskOnScore >= 85) {
  direction = 'risk_on';
  score = riskOnScore;
  reasons = riskOnReasons;
}
score = Math.min(140, score);
if (direction === 'neutral' || score < 100) return [];
const staticData = $getWorkflowStaticData('global');
const materialDelta = 20;
const sameDirection = staticData.lastDirection === direction;
const lastScore = Number(staticData.lastScore || 0);
const previousDirection = staticData.lastDirection || '';
let eventType = 'new_regime';
let shouldSend = false;
if (!sameDirection) {
  shouldSend = true;
  eventType = previousDirection ? 'reversal' : 'new_regime';
} else if (score >= lastScore + materialDelta) {
  shouldSend = true;
  eventType = 'material_worsening';
}
if (!shouldSend) return [];
staticData.lastDirection = direction;
staticData.lastScore = score;
staticData.lastAlertAt = Date.now();
const quoteLines = quotes.map(q => `${q.label}: ${q.close} (${q.pctFromPrevClose}%)`).join('\n');
const regime = direction === 'risk_off' ? 'RISK_OFF' : 'RISK_ON';
const intensity = score >= 125 ? 'extrema' : score >= 110 ? 'forte' : 'moderada';
const trendText = direction === 'risk_off' ? 'pressao vendedora em indice futuro Brasil' : 'alivio comprador em indice futuro Brasil';
const conviction = score >= 125 ? 'alta' : 'media-alta';
let whatChanged = '';
if (eventType === 'new_regime') whatChanged = `Novo regime detectado: ${regime}.`;
else if (eventType === 'reversal') whatChanged = `Reversao de ${previousDirection ? previousDirection.toUpperCase() : 'NEUTRAL'} para ${regime}.`;
else whatChanged = `Mesmo regime, mas score subiu de ${lastScore} para ${score}.`;
const winPlan = direction === 'risk_off' ? 'Priorize venda so se perder VWAP e a minima da abertura com dolar confirmando alta.' : 'Priorize compra so se sustentar VWAP e romper a maxima da abertura com dolar cedendo.';
const dollarPlan = direction === 'risk_off' ? 'Dolar deve confirmar fluxo defensivo. Se nao subir, a leitura perde qualidade.' : 'Dolar deve aliviar. Se nao ceder, a leitura compradora perde qualidade.';
const usPlan = direction === 'risk_off' ? 'ES/NQ devem permanecer negativos para validar continuidade do risk-off.' : 'ES/NQ devem sustentar alta para validar continuidade do risk-on.';
const discordText = `**MARKET REACTION | ${regime}${eventType === 'reversal' ? ' | REVERSAL' : eventType === 'material_worsening' ? ' | UPDATE' : ''}**\n\n**Regime:** ${regime}\n**Intensidade:** ${intensity}\n**Tendencia:** ${trendText}\n**Conviccao:** ${conviction}\n\n**O que mudou:** ${whatChanged}\n\n**Plano WIN:** ${winPlan}\n**Plano Dolar:** ${dollarPlan}\n**Plano Nasdaq/ES:** ${usPlan}\n\n**Score:** ${score}/140\n**Leituras:**\n${quoteLines}\n\n**Motivo:** ${reasons.join('; ')}\n**Fonte:** ${sourceMode === 'stooq' ? 'Stooq' : 'Yahoo Finance chart endpoint'}`;
return [{ json: { direction, regime, intensity, trendText, conviction, whatChanged, winPlan, dollarPlan, usPlan, score, eventType, quoteLines, reasons: reasons.join('; '), source: sourceMode === 'stooq' ? 'Stooq' : 'Yahoo Finance chart endpoint', generatedAt: new Date().toISOString(), note: 'Stale-data guard enabled.', discordText } }];
